# Adapted 2026-09-18. Modelled on as_run/subtypes/fit_lee_validation.R (external bulk symbol-input fit) and as_run/baseline/fit_external.R (GSE248784 route: harmonize() via hgnc_lookup.csv, then fit_one()).
# Changes from the as-run files: paths; input is the GEO GSE207362 human FeatureCounts table subset to the 38 published columns by suffix mapping; metadata built from the mapping; the single NA gene row (ANK2) is recorded before harmonize() drops it. No covariates (GEO records none per sample). fit_one() logic, filterByExpr/TMM/voom/robust eBayes unchanged.
suppressPackageStartupMessages({library(edgeR);library(limma)})
WD<-'<cluster_scratch>/gse207362_external_20260918';ROOT<-file.path(WD,'work');REF<-file.path(WD,'inputs/frozen/Analysis_code/reference_inputs');OUT<-file.path(WD,'outputs')
for(d in c('audit','figures','sensitivity','expression','per_study','logs'))dir.create(file.path(ROOT,d),showWarnings=FALSE,recursive=TRUE)
lookup <- read.csv(file.path(REF,'hgnc_lookup.csv'),check.names=FALSE,na.strings='')
namesym <- setNames(lookup$GeneSymbol,lookup$input_id)
namestatus <- setNames(lookup$mapping_status,lookup$input_id)
for(e in parse(file.path(WD,'scripts/fit_studies.R')))if(is.call(e)&&identical(e[[1]],as.name('<-'))&&as.character(e[[2]])%in%c('harmonize','read_matrix','fit_one'))eval(e)
d<-read.delim(pipe(paste('zcat',file.path(WD,'geo/GSE207362_Human_FeatureCounts.txt.gz'))),check.names=FALSE)
map<-read.csv(file.path(WD,'inputs/GSE207362_published_subset_mapping.csv'))
stopifnot(ncol(d)==68,all(map$count_column%in%colnames(d)),all(match(map$count_column,colnames(d))-1L==map$expression_column_1based))
m<-as.matrix(d[,map$count_column]);mode(m)<-'numeric';rownames(m)<-d[[1]]
na_rows<-rownames(m)[!complete.cases(m)]
write.csv(data.frame(GeneSymbol=na_rows,reason='NA counts in GEO deposit; dropped before harmonisation'),file.path(ROOT,'audit/GSE207362_dropped_NA_gene_rows.csv'),row.names=FALSE)
cat('GEO rows',nrow(m),'; NA rows dropped:',paste(na_rows,collapse=','),'\n')
m<-harmonize(m,'GSE207362',TRUE)
cat('harmonised genes',nrow(m),'from',attr(m,'source_rows'),'source rows\n')
sm<-data.frame(study='GSE207362',sample=map$count_column,condition=ifelse(map$publication_group=='rif','RIF','Control'),arm='rnaseq',tech='bulk',publication_group=map$publication_group,publication_index=map$publication_index,timing='HRT P+7',role='second_external_evaluation',mapping_assumption='paper within-group index = count-column suffix')
stopifnot(sum(sm$condition=='RIF')==12,sum(sm$condition=='Control')==26,!anyDuplicated(sm$sample))
fit_one('GSE207362',m,sm,TRUE,label='GSE207362_external')
write.csv(sm,file.path(ROOT,'audit/GSE207362_final_metadata.csv'),row.names=FALSE)
file.copy(file.path(ROOT,'sensitivity/GSE207362_external_DE.csv'),file.path(OUT,'GSE207362_external_DE.csv'),overwrite=TRUE)
# harmonised counts and unlogged CPM (UNBLOCK_1: needed if MetaRIF must run locally)
o<-readRDS(file.path(ROOT,'expression/GSE207362_external.rds'))
write.csv(data.frame(GeneSymbol=rownames(o$counts),o$counts,check.names=FALSE),gzfile(file.path(OUT,'GSE207362_harmonised_counts.csv.gz')),row.names=FALSE)
write.csv(data.frame(GeneSymbol=rownames(o$counts),cpm(o$counts,log=FALSE,normalized.lib.sizes=FALSE),check.names=FALSE),gzfile(file.path(OUT,'GSE207362_unlogged_CPM.csv.gz')),row.names=FALSE)
capture.output(sessionInfo(),file=file.path(ROOT,'logs/fit_gse207362_sessionInfo.txt'))
cat('GSE207362_FIT_COMPLETE\n')
